function MaidCoffeeMgr:StartLoadCat(catRoot)
    self.catBornGo = catRoot
    ---@type MaidCoffeeComponent
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    if maidCoffeeComponent then
        local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
        local isOther = maidCoffeeHomeDojo:IsOther()
        local t, seqKeys
        if isOther then
            t, seqKeys = maidCoffeeComponent:GetOtherShowCats()
        else
            t, seqKeys = maidCoffeeComponent:GetShowCats()
        end

        if #t > 0 and not isNull(seqKeys) then
            local seqId = KTool.XxHash32(table.concat(seqKeys, '-'))
            if self.preShowCatsId ~= seqId then
                self:DeleteCats()
                if not isNull(self.cat_coroutine) then
                    cs_coroutine.stop(self.cat_coroutine)
                    self.cat_coroutine = nil
                end
                self.preShowCatsId = seqId
                ---请求完成后构建猫
                self.cat_coroutine = cs_coroutine.start(function()
                    local isFinish = false
                    for i, v in pairs(t) do
                        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
                        local catVo = CatBallUtils.GetCatBallVo(v.catId)
                        local genes = catVo.kind
                        cs_coroutine.yield_return(eggComponent:LoadCatModelAsync(MaidCoffeeConstants.BornType.Adult, checkString(catVo.catId), false, genes, self.catBornGo.gameObject, function(go)
                            ---@type UnityEngine.Transform
                            local trans = go.transform
                            go.name = tostring(v.id)
                            KTool.SetLayer(self.catBornGo.gameObject, go, true)
                            local posIndex = math.random(1, #randomPos)
                            trans.localPosition = randomPos[posIndex]
                            trans.localRotation = Quaternion.Euler(0, 12, 0)
                            ---@type CatAI
                            local goEnv = AddLuaBehaviour(go, MaidCoffeeConstants.EnvPath.CatAIPath)
                            if isNull(goEnv.Env) then
                                goEnv:Init()
                            end
                            table.insert(self.cats, goEnv)
                            goEnv.Env:SetCatPlayerId(v.id, MaidCoffeeConstants.BornType.Adult)
                        end))
                    end
                    while not isFinish do
                        cs_coroutine.yield_return()
                    end
                end)
            end
        else
            ---要删除所有猫
            self:DeleteCats()
        end
    end
end

function MaidCoffeeMgr:GetCats()
    return self.cats
end

function MaidCoffeeMgr:DeleteCats()
    self.cats = {}
    self.preShowCatsId = nil
    if not isNull(self.catBornGo) and self.catBornGo.childCount > 0 then
        KTool.DestroyGameObjectChildren(self.catBornGo.gameObject)
    end
end

---判断店长 店员 外卖员 猫球是否解锁
function MaidCoffeeMgr:GetIsLocked(type, index)
    local refId = tonumber(100 * type + index)
    local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(refId)
    local desc = ""
    local isUnLocked = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockNum)
    if not isUnLocked then
        desc = GameUtils.GetUnlockDescr(vo.unlockType, vo.unlockNum)
    end
    return (not isUnLocked), desc
end

---获取当前套装描述
function MaidCoffeeMgr:GetCurMenuDes(index, isMeet)
    local group = self:GetMenuGroup()
    if isNull(self.recipeSchedules) then
        self:InitRecipeData()
    end
    local Des = ""
    if self.recipeSchedules[group][index][1] then
        Des = isMeet and self.recipeSchedules[group][index][1].name1 or self.recipeSchedules[group][index][1].name2
    end
    return Des or ""
end

function MaidCoffeeMgr:GetMenuGroup()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidHomeDoJo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    return maidHomeDoJo:GetCurGroup() or 1
end

