function MaidCoffeeMgr:GetCanGetRecipeInfo()
    if IsNull(self.menuFoodVos) then
        self:InitFoodVosByType()
    end
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    for i, j in pairs(self.menuFoodVos) do
        for _, v in pairs(j) do
            local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(v.refId)
            if not recipeDojo then
                local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.refId)
                if not isNull(foodVo) then
                    if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
                        local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                        local canJump = goodsConfMgr:CheckIsCanJump(row, false)
                        if canJump then
                            if isSet(foodVo, "jumpParameter") then
                                local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                                if type == Constants.IDType.QuestRegion then
                                    local isUnLock = ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                                    if isUnLock then
                                        return i, v.refId
                                    end
                                else
                                    canJump = goodsConfMgr:CheckIsCanJump(row, false)
                                    if canJump then
                                        return i, v.refId
                                    end
                                end
                            else
                                canJump = goodsConfMgr:CheckIsCanJump(row, false)
                                if canJump then
                                    return i, v.refId
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return 1, nil
end

function MaidCoffeeMgr:SortCardData(cards, sortType, asc, UIType)
    cards = checkTable(cards)
    local fieldNames = { "cafeEnergy", "star", "cardLevel", "cardId" }
    if fieldNames then
        ---装备稀有度排序
        table.sort(cards, function(a, b)
            return CommonChecker(a, b, fieldNames, asc)
        end)
    end
    return cards
end

