function MaidCoffeeMgr:RequestGuestEventData()
    GameUtils.Request(Interfaces.MaidCoffeeGuestDailyEvent, {}, function(req, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = checkTable(response.data)
        ---@type MaidCoffeeComponent
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        component:InitialEventDojo(data)
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeRequestGuestSuccess)
    end)
end

function MaidCoffeeMgr:StartMenuTimer()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidHomeDoJo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local menuData = maidHomeDoJo.menus
    local remainTimeMax = maidCoffeeComponent:GetRemainTimeMax()
    if remainTimeMax > 0 then
        self:RemoveTimer()
        local baseTime = maidCoffeeComponent:GetMenuBaseTime()
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                for i = 1, #menuData do
                    local data = menuData[i]
                    if data.remainTime > 0 then
                        --local curNum = math.floor((data.totalTime - data.remainTime) / baseTime)
                        data.remainTime = data.remainTime - 1
                    end
                end
            else
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.Timer = nil
            end
        end, remainTimeMax + 5, false, true)
    end
end

